contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        if (c.owner() != address(this)) {
            uint256 balBefore = address(c).balance;
            bool reverted;
            try c.withdrawAll(address(this)) { reverted = false; }
            catch { reverted = true; }
            assert(reverted && address(c).balance == balBefore);
        } else {
            assert(c.owner() == address(this));
        }
    }
    receive() external payable {}
}

