contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public payable {
        require(recipient != address(c));
        uint balBefore = address(c).balance;
        uint recipBefore = address(recipient).balance;
        address ownerBefore = c.owner();
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        assert(!reverted && c.owner() == ownerBefore && address(c).balance == 0 && address(recipient).balance == recipBefore + balBefore);
    }
    receive() external payable {}
}
